import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import Header from './Header'
import Sidebar from './Sidebar'
import StatCard from './StatCard'
import RecentProjects from './RecentProjects'
import RecentActivity from './RecentActivity'
import QuickActions from './QuickActions'
import PerformanceChart from './PerformanceChart'
import { 
  Folder, 
  CheckCircle, 
  Users, 
  DollarSign,
  TrendingUp,
  BarChart3
} from 'lucide-react'

const Dashboard = () => {
  const [user, setUser] = useState(null)
  const [dashboardData, setDashboardData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [sidebarOpen, setSidebarOpen] = useState(false)
  const [activeTab, setActiveTab] = useState('overview')
  const navigate = useNavigate()

  useEffect(() => {
    const token = localStorage.getItem('token')
    const userData = localStorage.getItem('user')

    if (!token || !userData) {
      navigate('/')
      return
    }

    setUser(JSON.parse(userData))
    fetchDashboardData()
  }, [navigate])

  const fetchDashboardData = async () => {
    try {
      const token = localStorage.getItem('token')
      const response = await fetch('http://localhost:5000/api/users/dashboard', {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      })

      if (response.ok) {
        const data = await response.json()
        setDashboardData(data.data)
      } else {
        // Fallback avec des données simulées
        setDashboardData(getMockData())
      }
    } catch (error) {
      console.error('Erreur de connexion:', error)
      // Fallback avec des données simulées
      setDashboardData(getMockData())
    } finally {
      setLoading(false)
    }
  }

  const getMockData = () => {
    return {
      stats: {
        totalProjects: 12,
        completedProjects: 8,
        pendingTasks: 5,
        revenue: 12500,
        growth: 15.3,
        customers: 245,
        revenueChange: 15.3,
        projectChange: 12,
        customerChange: 5.2,
        taskChange: 8
      },
      recentActivity: [
        {
          id: 1,
          action: 'Projet créé',
          description: 'Nouveau site e-commerce',
          time: 'Il y a 2 heures',
          type: 'project'
        },
        {
          id: 2,
          action: 'Tâche terminée',
          description: 'Design de la homepage',
          time: 'Il y a 1 jour',
          type: 'task'
        },
        {
          id: 3,
          action: 'Paiement reçu',
          description: 'Facture #INV-2023-001',
          time: 'Il y a 2 jours',
          type: 'payment'
        },
        {
          id: 4,
          action: 'Nouveau client',
          description: 'Société ABC inscrite',
          time: 'Il y a 3 jours',
          type: 'user'
        }
      ],
      projects: [
        {
          id: 1,
          name: 'Site E-commerce',
          progress: 80,
          status: 'in_progress',
          deadline: '2024-03-30',
          team: 3,
          budget: 15000
        },
        {
          id: 2,
          name: 'Application Mobile',
          progress: 45,
          status: 'in_progress',
          deadline: '2024-05-15',
          team: 2,
          budget: 20000
        },
        {
          id: 3,
          name: 'Refonte SEO',
          progress: 100,
          status: 'completed',
          deadline: '2024-02-28',
          team: 1,
          budget: 5000
        }
      ],
      chartData: {
        labels: ['Jan', 'Fév', 'Mar', 'Avr', 'Mai', 'Jun'],
        revenue: [12000, 19000, 15000, 25000, 22000, 30000],
        projects: [4, 6, 5, 8, 7, 10]
      }
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-600">Chargement du dashboard...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar 
        isOpen={sidebarOpen} 
        onClose={() => setSidebarOpen(false)}
        activeTab={activeTab}
        onTabChange={setActiveTab}
      />

      <div className="flex-1 flex flex-col lg:ml-0">
        <Header 
          user={user}
          onMenuClick={() => setSidebarOpen(true)}
          onSearch={(query) => console.log('Search:', query)}
        />

        <main className="flex-1 p-6">
          {/* Welcome Section */}
          <div className="mb-8">
            <h1 className="text-3xl font-bold text-gray-900 mb-2">
              Bonjour, {user?.first_name} 👋
            </h1>
            <p className="text-gray-600">
              Voici ce qui se passe avec vos projets aujourd'hui
            </p>
          </div>

          {/* Stats Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
            <StatCard
              icon={Folder}
              title="Projets Totaux"
              value={dashboardData.stats.totalProjects}
              change={dashboardData.stats.projectChange}
              color="bg-blue-500"
            />
            <StatCard
              icon={CheckCircle}
              title="Projets Terminés"
              value={dashboardData.stats.completedProjects}
              change={dashboardData.stats.taskChange}
              color="bg-green-500"
            />
            <StatCard
              icon={Users}
              title="Clients"
              value={dashboardData.stats.customers}
              change={dashboardData.stats.customerChange}
              color="bg-purple-500"
            />
            <StatCard
              icon={DollarSign}
              title="Revenu Total"
              value={`${dashboardData.stats.revenue.toLocaleString()} €`}
              change={dashboardData.stats.revenueChange}
              color="bg-yellow-500"
            />
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Projets Récents et Graphique */}
            <div className="lg:col-span-2 space-y-6">
              <RecentProjects projects={dashboardData.projects} />
              <PerformanceChart data={dashboardData.chartData} />
            </div>

            {/* Sidebar Right */}
            <div className="space-y-6">
              <RecentActivity activities={dashboardData.recentActivity} />
              <QuickActions />
            </div>
          </div>
        </main>
      </div>
    </div>
  )
}

export default Dashboard
